    /**
     * Method to retrieve the IoTDevice via an IoTDevicePrimaryKey.
     * @param 	id Long
     * @return 	IoTDevice
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public IoTDevice handle( FindIoTDeviceQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getIoTDeviceId() );
    }
    
    /**
     * Method to retrieve a collection of all IoTDevices
     *
     * @param	query	FindAllIoTDeviceQuery 
     * @return 	List<IoTDevice> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<IoTDevice> handle( FindAllIoTDeviceQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindIoTDevice,
 * but only if the id matches
 *
 * @param		entity	IoTDevice
 */
	protected void emitFindIoTDevice( IoTDevice entity ) {
		LOGGER.info("handling emitFindIoTDevice" );
		
	    queryUpdateEmitter.emit(FindIoTDeviceQuery.class,
	                            query -> query.getFilter().getIoTDeviceId().equals(entity.getIoTDeviceId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllIoTDevice
	 * 
	 * @param		entity	IoTDevice
	 */
	protected void emitFindAllIoTDevice( IoTDevice entity ) {
		LOGGER.info("handling emitFindAllIoTDevice" );
		
	    queryUpdateEmitter.emit(FindAllIoTDeviceQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(IoTDeviceProjector.class.getName());

